import {
  Button,
  FieldError,
  Group,
  Input,
  Label,
  SearchField as AriaSearchField,
  Text,
} from "react-aria-components";
import type {
  SearchFieldProps as AriaSearchFieldProps,
  ValidationResult,
} from "react-aria-components";
import { Search, X } from "./icons";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./SearchField.css";

type SearchFieldSize = ControlSize;

export interface SearchFieldProps extends Omit<AriaSearchFieldProps, "className" | "children"> {
  /**
   * Size axis.
   *
   * @default "medium"
   */
  size?: SearchFieldSize;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the input. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Input placeholder. */
  placeholder?: string;
  /** Additional class. sd-search-field is always retained. */
  className?: string;
  /** Passed to the underlying input DOM element. */
  ref?: Ref<HTMLInputElement>;
}

export function SearchField({
  size = "medium",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  className,
  ref,
  ...props
}: SearchFieldProps) {
  return (
    <AriaSearchField
      {...props}
      className={className ? `sd-search-field ${className}` : "sd-search-field"}
    >
      {({ isEmpty, isDisabled, isInvalid }) => (
        <>
          {/* RAC's Label spreads only labelProps and emits no state attributes, so relay
              isDisabled — otherwise `.sd-search-field__label[data-disabled]` never matches and a
              disabled field's label stays undimmed. Select/ComboBox relay it the same way. */}
          {contextualHelp ? (
            <div className="sd-search-field__label-group">
              {label && (
                <Label
                  data-disabled={isDisabled || undefined}
                  className={`sd-search-field__label sd-type-label-${roleSize(size)}`}
                >
                  {label}
                </Label>
              )}
              {contextualHelp}
            </div>
          ) : (
            label && (
              <Label
                data-disabled={isDisabled || undefined}
                className={`sd-search-field__label sd-type-label-${roleSize(size)}`}
              >
                {label}
              </Label>
            )
          )}
          {/* The Group is the bordered box (flex row of icon · input · clear), mirroring the
              ComboBox/NumberField pattern. It self-emits data-hovered/data-focus-within; the
              field's validity/disabled aren't in a GroupContext here (SearchField has none), so
              relay them so the box border reflects those states. */}
          <Group
            data-size={size}
            isDisabled={isDisabled}
            isInvalid={isInvalid}
            className="sd-search-field__group"
          >
            <span aria-hidden="true" data-size={size} className="sd-search-field__icon">
              <Search size="1em" />
            </span>
            <Input
              ref={ref}
              data-size={size}
              placeholder={placeholder}
              className={`sd-search-field__input sd-type-body-${roleSize(size)}`}
            />
            {/* No aria-label here: RAC's SearchField supplies a localized "Clear search"
                name to the clear button via ButtonContext; an explicit one would override it. */}
            <Button
              data-empty={isEmpty || undefined}
              data-size={size}
              className="sd-search-field__clear"
            >
              <X aria-hidden size="1em" />
            </Button>
          </Group>
          {description && (
            <Text slot="description" className={`sd-search-field__description sd-type-caption-${roleSize(size)}`}>
              {description}
            </Text>
          )}
          <FieldError className={`sd-search-field__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
        </>
      )}
    </AriaSearchField>
  );
}

.sd-search-field {
  --sd-search-field-group-background-current: var(--sd-search-field-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-search-field-gap);
}
.sd-search-field[data-readonly] {
  --sd-search-field-group-background-current: var(--sd-search-field-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-search-field__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-search-field-label-group-gap);
}

.sd-search-field__label {
  padding-inline: var(--sd-search-field-text-padding-inline);
  color: var(--sd-search-field-label-foreground);
}
.sd-search-field__label[data-disabled] {
  opacity: var(--sd-state-disabled);
}

/* The bordered box — a flex row of [icon · input · clear], matching the ComboBox/NumberField
   group pattern. Border/fill/radius live here (not on the input); the input is transparent.
   State comes from the RAC Group (data-hovered/focus-within/invalid/disabled).
   No `color` here, deliberately — the one place this diverges from the group template it follows.
   The template's `color: var(--sd-<field>-group-foreground)` came over with the pattern, but no
   token was ever added behind it (`search-field.group.foreground` is absent from tokens/cmp, and
   the variable does not exist in Figma either), so CSS dropped the whole declaration and it never
   painted anything. Nothing would inherit it in any case: `icon`, `input` and `clear` each set
   their own color, which makes SearchField the only member of the group family with no inheriting
   descendant (in the date/time fields it is the `__input` wrapper). So do not add the token to
   restore sibling symmetry — nothing would read it. Add it if a child that inherits its color is
   ever introduced here. */
.sd-search-field__group {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-medium);
  display: flex;
  align-items: center;
  gap: var(--sd-search-field-group-gap);
  width: 100%;
  background: var(--sd-search-field-group-background-current);
  border: var(--sd-search-field-group-border-width) solid var(--sd-search-field-group-border);
  border-radius: var(--sd-search-field-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-search-field__group[data-size="x-small"] {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-x-small);
  min-height: var(--sd-search-field-group-height-x-small);
  padding-inline: var(--sd-search-field-group-padding-inline-x-small);
}
.sd-search-field__group[data-size="small"] {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-small);
  min-height: var(--sd-search-field-group-height-small);
  padding-inline: var(--sd-search-field-group-padding-inline-small);
}
.sd-search-field__group[data-size="medium"] {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-medium);
  min-height: var(--sd-search-field-group-height-medium);
  padding-inline: var(--sd-search-field-group-padding-inline-medium);
}
.sd-search-field__group[data-size="large"] {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-large);
  min-height: var(--sd-search-field-group-height-large);
  padding-inline: var(--sd-search-field-group-padding-inline-large);
}
.sd-search-field__group[data-size="x-large"] {
  --sd-search-field-group-radius-current: var(--sd-search-field-group-radius-x-large);
  min-height: var(--sd-search-field-group-height-x-large);
  padding-inline: var(--sd-search-field-group-padding-inline-x-large);
}
.sd-search-field__group[data-hovered] {
  border-color: var(--sd-search-field-group-border-hover);
}
.sd-search-field__group[data-focus-within] {
  border-color: var(--sd-search-field-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-search-field__group[data-invalid] {
  border-color: var(--sd-search-field-group-border-invalid);
}
/* invalid + focused: tint the focus ring red so it doesn't clash with the red border
   (matches TextField's invalid-focus register). */
.sd-search-field__group[data-invalid][data-focus-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-search-field-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-search-field__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-search-field__icon {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--sd-search-field-icon-foreground);
  line-height: var(--sd-search-field-line-height-none);
  pointer-events: none;
}
/* Leading icon glyph rides the icon scale per size (12/16/20), like an icon-only Button. */
.sd-search-field__icon[data-size="x-small"] {
  font-size: var(--sd-search-field-icon-font-size-x-small);
}
.sd-search-field__icon[data-size="small"] {
  font-size: var(--sd-search-field-icon-font-size-small);
}
.sd-search-field__icon[data-size="medium"] {
  font-size: var(--sd-search-field-icon-font-size-medium);
}
.sd-search-field__icon[data-size="large"] {
  font-size: var(--sd-search-field-icon-font-size-large);
}
.sd-search-field__icon[data-size="x-large"] {
  font-size: var(--sd-search-field-icon-font-size-x-large);
}

.sd-search-field__input {
  flex: 1;
  min-width: 0;
  /* A value wider than the field ends in an ellipsis while it rests, not at a hard clip mid-glyph;
     focused, the input scrolls to the caret as it always has. */
  text-overflow: ellipsis;
  background: transparent;
  color: var(--sd-search-field-input-foreground);
  border: 0;
  outline: 0;
}
.sd-search-field__input::placeholder {
  color: var(--sd-search-field-input-placeholder);
}
/* Suppress the browser's native type="search" clear glyph so only the DS clear button shows
   (otherwise Chrome/WebKit paints a second ✕ beside ours). Same-element pseudo, like ::placeholder. */
.sd-search-field__input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
}

.sd-search-field__clear {
  position: relative;
  isolation: isolate;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* The UA's own `<button>` padding (`1px 6px` in Chrome) — `reset.css` only normalizes a button's
     font and color, not its box. The button's size is fixed here, so the padding does not resize it;
     it eats the CONTENT box instead, leaving the glyph 12px narrower than tall (measured 4×12 at
     small). `preserveAspectRatio` then scales the × down to fit that sliver, so the painted glyph was
     4×4 inside a 16px circle — and because the shortfall is a constant 12px, it hit each size
     differently (33% / 50% / 60% of the intended glyph) instead of Figma's even 75–83%. That uneven
     shrink is why the three sizes read as unrelated. */
  padding: 0;
  background: var(--sd-search-field-clear-background);
  color: var(--sd-search-field-clear-foreground);
  border: 0;
  border-radius: var(--sd-search-field-clear-radius);
  corner-shape: round;
  line-height: var(--sd-search-field-line-height-none);
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-search-field-clear-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-search-field-clear-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
}
/* Clear button box + glyph both scale per size (box 16/20/24, glyph 12/16/20). */
.sd-search-field__clear[data-size="x-small"] {
  width: var(--sd-search-field-clear-size-x-small);
  height: var(--sd-search-field-clear-size-x-small);
  font-size: var(--sd-search-field-clear-font-size-x-small);
}
.sd-search-field__clear[data-size="small"] {
  width: var(--sd-search-field-clear-size-small);
  height: var(--sd-search-field-clear-size-small);
  font-size: var(--sd-search-field-clear-font-size-small);
}
.sd-search-field__clear[data-size="medium"] {
  width: var(--sd-search-field-clear-size-medium);
  height: var(--sd-search-field-clear-size-medium);
  font-size: var(--sd-search-field-clear-font-size-medium);
}
.sd-search-field__clear[data-size="large"] {
  width: var(--sd-search-field-clear-size-large);
  height: var(--sd-search-field-clear-size-large);
  font-size: var(--sd-search-field-clear-font-size-large);
}
.sd-search-field__clear[data-size="x-large"] {
  width: var(--sd-search-field-clear-size-x-large);
  height: var(--sd-search-field-clear-size-x-large);
  font-size: var(--sd-search-field-clear-font-size-x-large);
}
.sd-search-field__clear[data-empty] {
  display: none;
}
/* RAC gives the clear button isDisabled = field isDisabled || isReadOnly, so it emits
   data-disabled — dim it to match the input's disabled treatment. */
.sd-search-field__clear[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
/* WCAG 2.2 (2.5.8) pointer target, the same transparent-pseudo idiom TagGroup and the three
   trigger chips use: the painted button keeps `clear.size` and only the target grows. Inert at
   `large`, where the box already meets 24. The clearance is DERIVED from tokens: the box is
   16/20/24 so the lift overflows 4/2/0 per side, the group's `padding.inline` and its 8 `group.gap`
   both exceed that at every size and brand, and the group's height (32/40/48) around the box leaves
   8/10/12 of half-clearance. The token's `$description` names the render check and its story. */
.sd-search-field__clear::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  min-width: var(--sd-search-field-clear-touch-target-size);
  min-height: var(--sd-search-field-clear-touch-target-size);
}
.sd-search-field__clear::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-search-field__clear[data-hovered]::after {
  background: var(--sd-search-field-clear-state-hover-current);
}
.sd-search-field__clear[data-pressed]::after {
  background: var(--sd-search-field-clear-state-pressed-current);
}
.sd-search-field__clear[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-search-field__description {
  padding-inline: var(--sd-search-field-text-padding-inline);
  color: var(--sd-search-field-description-foreground);
}
.sd-search-field__error {
  padding-inline: var(--sd-search-field-text-padding-inline);
  color: var(--sd-search-field-error-foreground);
}
